# Volume of the DryStoneMesh pulled box vs its box, for a few ROUGH values (same rng as add()).
func _init() -> void:
	for rough in [0.3, 0.2, 0.15, 0.1]:
		var sum := 0.0
		var n := 200
		for seed in n:
			var rng := RandomNumberGenerator.new()
			rng.seed = seed * 1009 + 3
			var pts: Array[Vector3] = []
			for c: Vector3 in DryStoneMesh.CORNERS:
				var pull := Vector3(rng.randf(), rng.randf(), rng.randf()) * rough
				pts.append(c * 0.5 * (Vector3.ONE - pull))
			var v := PackedVector3Array()
			for f: Array in DryStoneMesh.FACES:
				for tri in [[f[0], f[1], f[2]], [f[0], f[2], f[3]]]:
					for q in [tri[0], tri[2], tri[1]]:
						v.append(pts[q])
			sum += absf(StoneMesh.volume(v))
		print("ROUGH %.2f mean volume share %.3f -> scale to 0.96: %.3f" % [rough, sum / n, pow(0.96 / (sum / n), 1.0 / 3.0)])
	quit()
